"""Build three static design directions from verified website content.

Run `python build.py`, then `python -m http.server 8765 --directory dist`.
Only the Python standard library is required.
"""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).parent
OUT = ROOT / "dist"
SCHOLAR = "https://scholar.google.com/citations?user=irs_5ekAAAAJ&hl=en"
CV = "https://drive.google.com/drive/folders/1FvlEPuA5V5lDVFEz8fzwvr9fjEW6TRVS?usp=sharing"
PUBLICATIONS = [
    ("2026", "ScrapeBench: Evaluating Legal Compliance of AI Agents in Website Scraping", "Joseph Marvin Imperial, Daniel Slate, and Noam Kolt", "NeurIPS · Main", "governance", "", "Preprint forthcoming"),
    ("2026", "Rethinking Standard Compliance in the LLM Era", "Joseph Marvin Imperial, Matthew Jones, and Harish Tayyar Madabushi", "EMNLP · Findings", "governance", "https://arxiv.org/abs/2503.04736", "Read paper"),
    ("2026", "Scaling Policy Compliance Assessment in Language Models with Policy Reasoning Traces", "Joseph Marvin Imperial and Harish Tayyar Madabushi", "ICML · TAIGR Workshop", "governance", "https://arxiv.org/abs/2509.23291", "Read paper"),
    ("2026", "Safer Policy Compliance with Dynamic Epistemic Fallback", "Joseph Marvin Imperial and Harish Tayyar Madabushi", "ICML · AI for Law Workshop", "governance", "https://arxiv.org/abs/2601.23094", "Read paper"),
    ("2025", "UniversalCEFR: Enabling Open Multilingual Research on Language Proficiency Assessment", "Joseph Marvin Imperial and collaborators", "EMNLP · Main", "language", "https://universalcefr.github.io/", "View project"),
    ("2024", "Standardize: Aligning Language Models with Expert-Defined Standards for Content Generation", "Joseph Marvin Imperial, Gail Forey, and Harish Tayyar Madabushi", "EMNLP · Oral", "language", "https://imperialite.github.io/standardize/", "View project"),
    ("2024", "Near to Mid-term Risks and Opportunities of Open Source Generative AI", "Francisco Eiras and collaborators, including Joseph Marvin Imperial", "ICML · Oral", "governance", "https://arxiv.org/abs/2404.17047", "Read paper"),
]

def external(href, text, cls=""):
    return f'<a class="{cls}" href="{escape(href, quote=True)}" target="_blank" rel="noopener noreferrer">{text}<span aria-hidden="true"> ↗</span></a>'

def design_bar(active):
    links = ''.join(f'<a href="{key}.html" {"aria-current=page" if key == active else ""}><span>{num}</span> {name}</a>' for key,num,name in [('editorial','01','Editorial'),('precision','02','Precision'),('studio','03','Studio')])
    return f'<aside class="design-bar" aria-label="Design preview selector"><a class="design-home" href="index.html">DESIGN STUDIES <span>/ JOSEPH IMPERIAL</span></a><nav aria-label="Compare design directions">{links}</nav><span class="preview-note">CONCEPT PREVIEW</span></aside>'

def header():
    return '<header class="site-header wrap"><a class="brand" href="#top" aria-label="Joseph Imperial, home"><span class="monogram">ji<span>.</span></span><span class="brand-name">Joseph Imperial</span></a><nav aria-label="Main navigation"><a href="#research">Research</a><a href="#publications">Publications</a><a href="#about">About</a><a class="nav-contact" href="#contact">Get in touch <span aria-hidden="true">↗</span></a></nav></header>'

def affiliations():
    return '<div class="affiliations wrap"><span class="affiliation-label">CURRENTLY AT</span><a href="https://www.pivotal-research.org/" target="_blank" rel="noopener noreferrer">Pivotal Research <span>Technical AI Governance Fellow</span></a><a href="https://www.bath.ac.uk/" target="_blank" rel="noopener noreferrer">University of Bath <span>PhD Candidate · UKRI CDT in ART-AI</span></a><span class="location"><i></i> Based in the United Kingdom</span></div>'

def paper_rows():
    rows=[]
    for i,(year,title,authors,venue,topic,url,label) in enumerate(PUBLICATIONS):
        link=external(url, label, 'paper-link') if url else '<span class="forthcoming">Preprint forthcoming</span>'
        title_html=external(url, escape(title), 'paper-title-link') if url else escape(title)
        rows.append(f'<article class="paper" data-topic="{topic}"><span class="paper-number">{i+1:02d}</span><div class="paper-main"><div class="paper-meta"><span>{year}</span><span>{venue}</span></div><h3>{title_html}</h3><p>{escape(authors)}</p></div><div class="paper-action">{link}</div></article>')
    return ''.join(rows)

def publications():
    return f'''<section class="publications wrap section" id="publications"><div class="section-heading"><div><p class="eyebrow">02 / SELECTED WORK</p><h2>Research, in practice.</h2></div>{external(SCHOLAR, 'Complete publication list', 'text-link')}</div><div class="publication-controls"><div class="filter-buttons" role="group" aria-label="Filter publications"><button class="active" type="button" data-filter="all" aria-pressed="true">All research <span>07</span></button><button type="button" data-filter="governance" aria-pressed="false">AI safety & governance</button><button type="button" data-filter="language" aria-pressed="false">Language & NLP</button></div><span class="publication-count" aria-live="polite">7 selected publications</span></div><div class="papers">{paper_rows()}</div></section>'''

def research():
    return '''<section class="research section" id="research"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">01 / RESEARCH FOCUS</p><h2>Three connected questions.</h2></div><p class="section-intro">How can we make increasingly capable AI systems safe, lawful, and accountable?</p></div><div class="research-grid"><article class="research-item"><span class="research-number">01</span><svg class="research-icon" viewBox="0 0 100 72" fill="none" aria-hidden="true"><path d="M50 5v61M18 19h64M25 19 9 48h32L25 19ZM75 19 59 48h32L75 19ZM31 66h38"/><circle cx="50" cy="16" r="5"/></svg><h3>Can AI follow the law?</h3><p>Legal alignment of AI agents, with benchmarks that test how agents respond to real legal obligations.</p><a href="#publications" data-research-filter="governance">Legal alignment <span aria-hidden="true">↗</span></a></article><article class="research-item"><span class="research-number">02</span><svg class="research-icon" viewBox="0 0 100 72" fill="none" aria-hidden="true"><rect x="12" y="7" width="76" height="58" rx="2"/><path d="m24 25 5 5 10-12M47 25h27m-50 25 5 5 10-12M47 50h27"/></svg><h3>How do we test compliance?</h3><p>Evaluating how language models interpret policies, reason through constraints, and meet expert-defined standards.</p><a href="#publications" data-research-filter="governance">Evaluation & standards <span aria-hidden="true">↗</span></a></article><article class="research-item"><span class="research-number">03</span><svg class="research-icon" viewBox="0 0 100 72" fill="none" aria-hidden="true"><path d="M8 12h50v35H30L18 59V47H8V12ZM65 26h27v35H78L67 69v-8H45V53"/><path d="M19 23h28M19 34h20"/></svg><h3>Who does language AI serve?</h3><p>Multilingual language assessment and NLP, extending research across languages, proficiency levels, and communities.</p><a href="#publications" data-research-filter="language">Language & accessibility <span aria-hidden="true">↗</span></a></article></div></div></section>'''

def news():
    return '''<section class="news wrap section"><div class="section-heading"><div><p class="eyebrow">RECENT DEVELOPMENTS</p><h2>From the research desk.</h2></div><span class="small-note">Latest updates from my work</span></div><div class="news-grid"><article><span class="news-tag">PUBLICATIONS / 2026</span><h3>Three papers accepted at NeurIPS.</h3><p>ScrapeBench, GlobalPIQA, and Jarvis-Bench have been accepted to NeurIPS 2026. Preprints forthcoming.</p></article><article><span class="news-tag">PUBLICATIONS / 2026</span><h3>Two papers heading to EMNLP.</h3><p>ComplexityMT and a position paper on rethinking standard compliance in language models.</p><a href="https://arxiv.org/abs/2503.04736" target="_blank" rel="noopener noreferrer">Read the position paper <span aria-hidden="true">↗</span></a></article><article><span class="news-tag">BENCHMARKS</span><h3>Humanity’s Last Exam, in Nature.</h3><p>Our collaborative benchmark for evaluating the capabilities of frontier AI models is now published in Nature.</p><a href="https://www.nature.com/articles/s41586-025-09962-4" target="_blank" rel="noopener noreferrer">Read in Nature <span aria-hidden="true">↗</span></a></article></div></section>'''

def about():
    return f'''<section class="about section" id="about"><div class="wrap about-grid"><div class="about-copy"><p class="eyebrow">03 / A LITTLE CONTEXT</p><h2>Technical depth.<br>A human perspective.</h2><p class="lead">I’m Joseph, a researcher working at the intersection of technical AI safety and governance.</p><p>My research focuses on the legal alignment of AI agents and the compliance capabilities of language models. At Pivotal Research, I work with <a href="https://www.noamkolt.com/" target="_blank" rel="noopener noreferrer">Noam Kolt</a>. I also collaborate with Ben Brady and Cullen O’Keefe at the Institute for Law & AI on benchmarking law-following AI.</p><p>Before moving to the UK, I worked as a Senior NLP Researcher at National University in the Philippines, managing its Human Language Technology Lab.</p>{external(CV, 'View curriculum vitae', 'text-link')}</div><div class="timeline"><p class="eyebrow">EXPERIENCE & EDUCATION</p><article><span>2026 — PRESENT</span><h3>Technical AI Governance Fellow</h3><p>Pivotal Research · London Initiative for Safe AI</p></article><article><span>2022 — EXPECTED 2026</span><h3>PhD in Accountable, Responsible,<br>and Transparent AI</h3><p>University of Bath · UKRI CDT in ART-AI</p></article><article><span>2018 — ON STUDY LEAVE</span><h3>Senior NLP Researcher</h3><p>National University, Philippines</p></article><article><span>2018 — 2021</span><h3>MSc in Computer Science</h3><p>De La Salle University, Philippines</p></article><div class="recognition"><span class="eyebrow">RECOGNITION</span><p>Doctoral Recognition Award · Bath, 2024<br>Researcher of the Year · NU, 2023<br>Outstanding Reviewer · ICML, 2026 & 2024; ACL, 2023</p></div></div></div></section>'''

def media():
    return '''<section class="media wrap section"><p class="eyebrow">IN CONVERSATION</p><div class="media-heading"><h2>Beyond the paper.</h2><p>Discussing AI research and its implications.</p></div><a href="https://aihub.org/2025/04/02/interview-with-joseph-marvin-imperial-aligning-generative-ai-with-technical-standards/" target="_blank" rel="noopener noreferrer"><span class="media-outlet">AIhub</span><span>Aligning generative AI with technical standards</span><span aria-hidden="true">↗</span></a><a href="https://www.newscientist.com/article/2473622-leading-ai-models-fail-new-test-of-artificial-general-intelligence/" target="_blank" rel="noopener noreferrer"><span class="media-outlet">New Scientist</span><span>The future of evaluating general AI capabilities</span><span aria-hidden="true">↗</span></a><a href="https://www.newsweek.com/openai-warns-us-government-agencies-of-rogue-activity-12492213" target="_blank" rel="noopener noreferrer"><span class="media-outlet">Newsweek</span><span>What agent swarm hacking means for AI safety</span><span aria-hidden="true">↗</span></a></section>'''

def contact():
    return f'''<footer id="contact" class="contact"><div class="wrap"><div class="contact-main"><div><p class="eyebrow">04 / GET IN TOUCH</p><h2>Let’s work<br>together<span>.</span></h2></div><div class="contact-details"><p>I welcome research collaborations across AI safety, law, governance, and natural language processing.</p><a class="email" href="mailto:jmri20@bath.ac.uk">jmri20@bath.ac.uk <span aria-hidden="true">↗</span></a><div class="social-links">{external(SCHOLAR,'Scholar')}{external('https://github.com/imperialite','GitHub')}{external('https://www.linkedin.com/in/josephimperial/','LinkedIn')}{external('https://x.com/josephimperial_','X')}{external('https://aclanthology.org/people/joseph-marvin-imperial/','ACL Anthology')}</div></div></div><div class="footer-base"><span>© 2026 Joseph Imperial</span><span>AI safety · Governance · Language</span><a href="#top">Back to top ↑</a></div></div></footer>'''

HERO_A = '''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> JOSEPH IMPERIAL / AI RESEARCHER</p><h1>Making AI<br><em>accountable.</em></h1><p class="hero-description">I study how AI systems can follow laws, meet standards, and align with human values.</p><div class="hero-actions"><a class="button primary" href="#publications">Explore my research <span aria-hidden="true">↗</span></a><a class="quiet-link" href="#about">A little about me <span aria-hidden="true">↓</span></a></div><div class="hero-footnote"><span class="tiny-line"></span> Technical AI safety. Legal alignment. Language.</div></div><div class="portrait-composition"><div class="orbit-art" aria-hidden="true"><i></i><i></i><i></i><span>AI × LAW × LANGUAGE</span></div><figure><img src="assets/joseph-imperial.jpg" alt="Joseph Imperial" width="1015" height="1131" fetchpriority="high"><figcaption><span>Joseph Imperial</span><span>Researcher · United Kingdom</span></figcaption></figure><span class="portrait-side-label">RESEARCH WITH REAL-WORLD CONSEQUENCES</span></div></section>'''

MAP = '''<div class="system-map" aria-label="Research themes connecting AI agents with law, evaluation, and language"><div class="map-topline"><span>RESEARCH SYSTEM / 01</span><span class="map-dot"></span></div><svg viewBox="0 0 460 400" role="img" aria-label="AI agents connected to legal alignment, compliance evaluation, and language research"><defs><pattern id="mapgrid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="0.7" fill="currentColor" opacity=".24"/></pattern></defs><rect width="460" height="400" fill="url(#mapgrid)"/><g fill="none" stroke="currentColor"><circle cx="230" cy="200" r="138" opacity=".12"/><circle cx="230" cy="200" r="98" opacity=".22"/><path d="M230 65v79M114 267l67-40M346 267l-68-40" opacity=".5"/><circle cx="230" cy="200" r="53"/><circle cx="230" cy="62" r="7" fill="currentColor"/><circle cx="111" cy="270" r="7" fill="currentColor"/><circle cx="349" cy="270" r="7" fill="currentColor"/></g><g fill="currentColor" text-anchor="middle" font-family="DM Sans, sans-serif"><text x="230" y="195" font-size="14" font-weight="600">AI AGENTS</text><text x="230" y="215" font-size="9" opacity=".55">BEHAVIOR & CAPABILITY</text><text x="230" y="35" font-size="11">LEGAL ALIGNMENT</text><text x="107" y="306" font-size="11">EVALUATION</text><text x="351" y="306" font-size="11">LANGUAGE</text></g></svg><div class="map-bottomline"><span>CAPABILITY → RESPONSIBILITY</span><span>JI / RESEARCH</span></div></div>'''

HERO_B = f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> JOSEPH IMPERIAL / AI RESEARCHER</p><h1>AI SAFETY.<br>GROUNDED IN<br><span>EVIDENCE.</span></h1><p class="hero-description">Evaluating how AI systems follow laws, comply with policies, and meet human-defined standards.</p><div class="hero-actions"><a class="button primary" href="#publications">Explore the research <span aria-hidden="true">↗</span></a><a class="quiet-link" href="#contact">Get in touch ↗</a></div></div><div class="precision-visual">{MAP}<div class="researcher-line"><img src="assets/joseph-imperial.jpg" alt="Joseph Imperial" width="54" height="54"><div><strong>Joseph Imperial</strong><span>Technical AI Governance Fellow · Pivotal Research</span></div><a href="#about" aria-label="About Joseph Imperial">↗</a></div></div></section>'''

HERO_C = '''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">AI RESEARCHER. COLLABORATOR. QUESTION ASKER.</p><h1>Joseph<br>Imperial<span class="name-period">.</span></h1><div class="studio-intro"><span class="asterisk" aria-hidden="true">✳</span><p>I work on making AI<br><strong>safe, lawful, and accountable.</strong></p></div><div class="hero-actions"><a class="button primary" href="#publications">Discover my work <span aria-hidden="true">↗</span></a><a class="quiet-link" href="#about">Meet the researcher ↓</a></div></div><div class="studio-portrait"><div class="portrait-halo" aria-hidden="true"></div><img src="assets/joseph-imperial.jpg" alt="Joseph Imperial" width="1015" height="1131" fetchpriority="high"><span class="portrait-sticker">AI + LAW<br>+ LANGUAGE</span><p><span class="status-dot"></span> The Philippines → The United Kingdom</p></div></section><div class="studio-statement"><div class="wrap"><span>CAPABLE SYSTEMS.</span><span>ACCOUNTABLE AI.</span><span aria-hidden="true">↗</span></div></div>'''

def page(theme, title, hero):
    desc="Joseph Imperial researches technical AI safety, legal alignment of AI agents, and language model compliance. Pivotal Research Fellow and University of Bath PhD candidate."
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="{'#141a20' if theme=='precision' else '#f4f2eb'}"><meta name="robots" content="noindex,nofollow"><title>Joseph Imperial · {title} design</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/fonts.css"><link rel="stylesheet" href="styles.css"><script src="site.js" defer></script></head><body class="{theme}" id="top"><a class="skip-link" href="#main">Skip to content</a>{design_bar(theme)}{header()}<main id="main">{hero}{affiliations()}{research()}{publications()}{news()}{about()}{media()}</main>{contact()}</body></html>'''

for theme,title,hero in [('editorial','Editorial',HERO_A),('precision','Precision',HERO_B),('studio','Studio',HERO_C)]:
    (OUT / f'{theme}.html').write_text(page(theme,title,hero), encoding='utf-8')

INDEX = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Three distinct website designs for Joseph Imperial."><title>Joseph Imperial · Design studies</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/fonts.css"><link rel="stylesheet" href="styles.css"></head><body class="gallery"><main class="gallery-wrap"><div class="gallery-top"><a href="index.html">JI / DESIGN STUDIES</a><span>THREE DIRECTIONS. ONE RESEARCHER.</span></div><header class="gallery-heading"><p class="eyebrow">A NEW HOME FOR YOUR WORK</p><h1>Choose your<br><em>point of view.</em></h1><p>Three distinct directions for your academic website.<br>Real content. Working layouts. Different personalities.</p></header><div class="concepts"><a class="concept" href="editorial.html"><div class="concept-preview preview-editorial"><div class="mini-nav">ji. <span>Research &nbsp; Publications &nbsp; About</span></div><div class="mini-hero"><div><span class="mini-label">JOSEPH IMPERIAL / AI RESEARCHER</span><h2>Making AI<br><em>accountable.</em></h2><p>Technical AI safety, legal alignment,<br>and language.</p><span class="mini-button">Explore my research ↗</span></div><img src="assets/joseph-imperial.jpg" alt="Portrait in the Editorial design" width="1015" height="1131"></div><div class="mini-bottom">Pivotal Research <span>University of Bath</span></div></div><div class="concept-label"><span>01 / EDITORIAL</span><span aria-hidden="true">↗</span></div><h2>Quiet authority.</h2><p>Warm paper, forest green, expressive serif type. A thoughtful, established academic presence.</p><span class="view-concept">Explore this direction <span aria-hidden="true">→</span></span></a><a class="concept" href="precision.html"><div class="concept-preview preview-precision"><div class="mini-nav">ji. <span>Research &nbsp; Publications &nbsp; About</span></div><div class="mini-hero"><div><span class="mini-label">JOSEPH IMPERIAL / AI RESEARCHER</span><h2>AI SAFETY.<br>GROUNDED IN<br><em>EVIDENCE.</em></h2><span class="mini-button">Explore the research ↗</span></div><div class="mini-map" aria-hidden="true"><span>AI AGENTS</span></div></div><div class="mini-bottom">Pivotal Research <span>University of Bath</span></div></div><div class="concept-label"><span>02 / PRECISION</span><span aria-hidden="true">↗</span></div><h2>Technical confidence.</h2><p>Graphite, cool blue, structured typography. A crisp identity grounded in research and evaluation.</p><span class="view-concept">Explore this direction <span aria-hidden="true">→</span></span></a><a class="concept" href="studio.html"><div class="concept-preview preview-studio"><div class="mini-nav">ji. <span>Research &nbsp; Publications &nbsp; About</span></div><div class="mini-hero"><div><span class="mini-label">RESEARCHER. COLLABORATOR.</span><h2>Joseph<br>Imperial<span>.</span></h2><p>Making AI safe, lawful,<br>and accountable.</p><span class="mini-button">Discover my work ↗</span></div><img src="assets/joseph-imperial.jpg" alt="Portrait in the Studio design" width="1015" height="1131"></div><div class="mini-bottom">CAPABLE SYSTEMS. <span>ACCOUNTABLE AI. ↗</span></div></div><div class="concept-label"><span>03 / STUDIO</span><span aria-hidden="true">↗</span></div><h2>A distinctive presence.</h2><p>Bright white, cobalt, bold type, and a prominent portrait. Personal, contemporary, and memorable.</p><span class="view-concept">Explore this direction <span aria-hidden="true">→</span></span></a></div><footer class="gallery-footer"><span>Each direction includes research, publications, background, media, and contact.</span><span>Switch designs from the bar at the top of every preview.</span></footer></main></body></html>'''
(OUT / 'index.html').write_text(INDEX, encoding='utf-8')

manifest_path=ROOT / '.openai' / 'hosting.json'
manifest=json.loads(manifest_path.read_text(encoding='utf-8-sig'))
manifest['static']={'directory':'dist'}
manifest_path.write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
print('Built gallery and three complete design previews.')
